import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import Database from 'better-sqlite3';
import { MasterData } from './master-data';
import { MasterDbMissing } from './master.errors';

/**
 * The committed master extract: 6 of master.mdb's 416 tables as SQL text,
 * generated by scripts/build-master-extract.mjs.
 *
 * This is what the API serves by default and what the tests read, so a passing
 * test says something about the running product rather than about a bespoke
 * subset built only for tests.
 */

/**
 * Probed rather than resolved from `__dirname` or `import.meta`: this module is
 * compiled to CommonJS for NestJS and read as ESM by Vitest, and neither anchor
 * exists in both. MASTER_EXTRACT_PATH overrides.
 */
export function findExtract(): string {
  const candidates = [
    process.env.MASTER_EXTRACT_PATH,
    resolve(__filename, '../../../data/master-extract.sql'),
    resolve(process.cwd(), 'data/master-extract.sql'),
    resolve(process.cwd(), 'packages/api/data/master-extract.sql'),
  ].filter((c): c is string => typeof c === 'string');

  for (const path of candidates) if (existsSync(path)) return path;
  throw new MasterDbMissing(
    candidates[0] ?? 'data/master-extract.sql',
    new Error(
      'no master extract found. Run: npm run build:master --workspace @umalegacies/api',
    ),
  );
}

export function readExtract(): string {
  return readFileSync(findExtract(), 'utf8');
}

/**
 * A fresh in-memory database built from the extract. Callers may mutate it
 * freely to simulate a drifted extraction; each call builds a new one.
 */
export function extractDatabase(): Database.Database {
  const db = new Database(':memory:');
  db.exec(readExtract());
  return db;
}

export function extractMaster(): MasterData {
  return new MasterData(extractDatabase());
}

/** SHA-256 of the extract, matching what GET /master/meta reports. */
export function extractHash(): string {
  return createHash('sha256').update(readFileSync(findExtract())).digest('hex');
}

/** Reads a `-- key: value` line out of the generated header. */
export function extractHeader(sql: string, key: string): string | null {
  const match = sql.match(new RegExp(`^-- ${key}: (.+)$`, 'm'));
  return match?.[1]?.trim() ?? null;
}
